'use strict';

// MODULES //

var isUndefined = require( '@stdlib/assert/is-undefined' );
var general = require( './transforms/general.js' );
var title = require( './transforms/title.js' );
var axes = require( './transforms/axes.js' );


// MAIN //

/**
* Returns a transformed visualization specification which replaces property values with signals for use in conjunction with UI components.
*
* @private
* @param {Object} schema - visualization specification
* @param {Object} defaults - UI defaults
* @returns {Object} transformed specification
*/
function transform( schema, defaults ) {
	var out;

	out = {};

	// Vega defines built-in height, width, and padding signals, so we can simply copy over...
	out.height = ( isUndefined( schema.height ) ) ? defaults.height : schema.height;
	out.width = ( isUndefined( schema.width ) ) ? defaults.width : schema.width;
	out.padding = ( isUndefined( schema.padding ) ) ? defaults.padding : schema.padding;

	// For the following properties, we simply copy them over, as no need to setup signals as they will not be associated with UI elements...
	out.autosize = schema.autosize;
	out.config = schema.config || {};
	out.data = schema.data || [];
	out.encode = schema.encode || {};
	out.usermeta = schema.usermeta || {};

	// Because we'll be adding to the list of signals, make a fresh (shallow) copy to avoid mutating the input schema:
	out.signals = ( schema.signals ) ? schema.signals.slice() : [];

	// Initialize the background and description properties:
	out.background = schema.background || void 0;
	out.description = schema.description || void 0;

	// Perform schema transformations...
	out = general( out, out.signals, defaults );
	if ( schema.title ) {
		out.title = title( schema.title, out.signals, defaults.title );
	}
	if ( schema.axes && schema.axes.length ) {
		out.axes = axes( schema.axes, out.signals, defaults.axis );
	}

	// FIXME: the following properties in order of priority
	out.scales = schema.scales;
	out.marks = schema.marks;
	out.legends = schema.legends;
	out.projections = schema.projections;

	return out;
}


// EXPORTS //

module.exports = transform;
